// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amountToFund) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amountToFund);
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;
        assertTrue(( !reverted && afterC == 0 && afterMe == beforeMe + beforeC )
            ||
            ( reverted && afterC == beforeC && afterMe == beforeMe ));
    }

    function testFuzz_run(uint256 amountToFund) public {
        _run(amountToFund);
    }

    receive() external payable {}
}
